int set_posix_acl(struct inode *inode, struct posix_acl *acl, int type) {
    int ret = 0;

    if (!inode || !acl) {
        return -EINVAL;
    }

    if (type != ACL_TYPE_ACCESS && type != ACL_TYPE_DEFAULT) {
        return -EINVAL;
    }

    if (type == ACL_TYPE_ACCESS) {
        ret = posix_acl_update_mode(inode, &acl->a_mode);
        if (ret) {
            return ret;
        }
    }

    inode->i_ctime = current_time(inode);

    if (type == ACL_TYPE_ACCESS) {
        inode->i_acl = acl;
    } else {
        inode->i_def_acl = acl;
    }

    return 0;
}
